// th14_s7_b6 — TH14 v1.00b Extra BossCard3 (spellEx112), source st07bs.ecl.txt:1509-1553.
// Source frame 0 starts after the 120-frame shell buffer (pattern waits OPENING_BUFFER).
// Boss = real enemy at (0,128) moving to (0,144); three TaikoA02 children carry the attack.
// 2号 funcCall/画面省略：本卡闭包内没有 funcSet/funcCall。

const TIME_LIMIT: int = 3424;      // 120 buffer + 3000 source timer + 300 tail + 4 startup
const OPENING_BUFFER: int = 120;
const SPELL_CARD3: int = 112;      // source spellEx(112, ...)

const BOSS_HIT_R: int = 24;        // context Boss() setHitbox(48,48): circular branch 48*0.5
const TAIKO_HIT_R: int = 16;       // TaikoA02 setHitbox(32,40): circular branch 32*0.5
const TAIKO_HURT_R: int = 16;      // TaikoA02 setHurtbox(32,48): circular branch 32*0.5

// moveEllipse(phase=pi/2, omega=0.008726646 rad, r=F4, d=0, axis=pi/2, s=0)
// -> x(t) = C.x + F4*cos(theta), y(t)=C.y, theta += 91 BAM (0.5 deg) per tick.
const ELLIPSE_PHASE0: int = 16384; // pi/2 in BAM
const ELLIPSE_OMEGA: int = 91;     // 0.008726646 rad in BAM

// TaikoA02_at emitter parameters (rad converted to BAM, nearest int).
const A60: int = 10923;            // 1.047198 rad = 60 deg (F2 of first Taiko)
const A120: int = 21845;           // 2.094395 rad = 120 deg (F2 of second Taiko)
const A90: int = 16384;            // 1.570796 rad = 90 deg (F2 of third Taiko)
const SPIN_POS: int = 91;          // 0.008727 rad = 0.5 deg (F3 of first Taiko)
const SPIN_NEG: int = -91;         // -0.008727 rad (F3 of second Taiko)
const SPREAD10: int = 1820;        // 0.17453292 rad
const SPREAD20: int = 3641;        // 0.34906584 rad
const SPREAD30: int = 5461;        // 0.5235988 rad

// Boss moveRand(60, 0, 0.6f) + moveLimit(0,128,280,64): position x[-140,140], y[96,160].
const BOSS_STEP_FRAMES: int = 60;  // speed 0.6*(60-k)/60 = (60-k)*0.01

async sub taiko_rot(a0: int, da: int) {
    // TaikoA02_rot02: B starts 60, fires while B>120 and B%60==59 (first at B=179),
    // each fire adds an extra wait(20); A advances by F3 every iteration.
    var a: int = a0;
    var b: int = 60;
    loop {
        if b > 120 && b % 60 == 59 {
            taiko_fire(a as angle);
            wait(20);
        }
        wait(1);
        a = a + da;
        b = b + 1;
    }
}

// TaikoA02_at: one volley. Emitter configs rebuilt per group, all from slot 0, same frame.
sub taiko_fire(a: angle) {
    // group 1: etAim(3) ring, etSprite(32,6), etCount(2,1), etAngle(A,pi), etSpeed(4.0,0.7)
    var sp: fx = 4fx;
    var back: fx = 4fx * sp;       // ANIM spawn retraction: position -= 4*velocity
    _ = fire(TH14_GLOW_BALL, 6, $self_x - back * cos(a), $self_y - back * sin(a), sp, a, none, none);
    var opp: angle = a + 180deg;
    _ = fire(TH14_GLOW_BALL, 6, $self_x - back * cos(opp), $self_y - back * sin(opp), sp, opp, none, none);

    // groups 2-4: etAim(8) random angle+speed, etSprite(19,6), etCount(6,1),
    // etAngle(A,dA) then etAngle(A+pi,dA) with a second etOn.
    taiko_burst(a, SPREAD10, 3fx);
    taiko_burst(a + 180deg, SPREAD10, 3fx);
    taiko_burst(a, SPREAD20, 2fx);
    taiko_burst(a + 180deg, SPREAD20, 2fx);
    taiko_burst(a, SPREAD30, 1fx);
    taiko_burst(a + 180deg, SPREAD30, 1fx);
}

// mode 8: per bullet angle = center + U_signed*span, speed = s0 + U*0.7; angle drawn first.
sub taiko_burst(center: angle, span: int, s0: fx) {
    for i in 0..6 {
        var ra: int = rand(65536);
        var u: fx = (ra - 32768) as fx / 32768;
        var off: int = ((span as fx) * u) as int;
        var ang: angle = center + (off as angle);
        var rv: int = rand(65536);
        var u2: fx = (rv - 32768) as fx / 65536 + 0.5fx;
        var sp: fx = s0 + u2 * 0.7fx;
        var back: fx = 4fx * sp;
        _ = fire(TH14_BIG_BALL2, 6, $self_x - back * cos(ang), $self_y - back * sin(ang), sp, ang, none, none);
    }
}

async sub taiko_main(x0: fx, y0: fx, amp: fx, a0: int, da: int) {
    // TaikoA02: body box kept as circular r=16 approximation (source 32x40 rect + hitboxRotate).
    set_invuln(65535);
    set_hitbox(TAIKO_HIT_R as fx);
    set_hurtbox(TAIKO_HURT_R as fx);
    // TaikoDead2 is visual only (anmPlay/sound/delete); no DPS shell never triggers it.
    spawn taiko_rot(a0, da);
    // movePosTime(120, 4, F0, F1): mode 4 = quadratic decel.
    move_to(120, x0, y0, EASE_QUAD_OUT);
    wait(120);
    // moveEllipse captures C at the current position, then sweeps horizontally.
    var theta: int = ELLIPSE_PHASE0;
    loop {
        theta = theta + ELLIPSE_OMEGA;
        var nx: fx = x0 + amp * cos(theta as angle);
        move_vel_xy(0, nx - $self_x, y0 - $self_y, EASE_LINEAR);
        wait(1);
    }
}

// ---- boss moveRand(60, 0, 0.6f), shared recipe (transcribe/th16/movement.md) ----
sub boss_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < BOSS_STEP_FRAMES { speed = ((60 - k) as fx) * 0.01fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    boss_arm_next_step();
}

sub boss_move_rand() {
    // Direction branch uses the inner quarter of the limit: |x|<=70, y in 112..144.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_angle(a as angle);
}

sub boss_card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        boss_arm_next_step();
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(BOSS_HIT_R as fx);
    set_hurtbox(BOSS_HIT_R as fx);
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    // movePosTime(60, 4, 0, 144) at card frame 0; stays inside moveLimit(0,128,280,64).
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    // +60/+150 visual intro omitted; BossCard3_at creates three TaikoA02 at frame 150,
    // each with its own F0..F4 snapshot passed by value.
    wait(150);
    _ = spawn_enemy($self_x, $self_y, 500, 0, 10, 0, taiko_main(180fx, 256fx, 16fx, A60, SPIN_POS));
    _ = spawn_enemy($self_x, $self_y, 500, 0, 10, 0, taiko_main(-180fx, 256fx, 16fx, A120, SPIN_NEG));
    _ = spawn_enemy($self_x, $self_y, 500, 0, 10, 0, taiko_main(0fx, 192fx, 160fx, A90, 0));
    // BossCard3_at's own wait(120) has no further effect.
    wait(180);
    // moveRand + wait(180) cycles from source frame 330 up to the 3000 timer.
    for i in 0..14 {
        boss_move_rand();
        boss_card_wait(180);
    }
    boss_move_rand();
    boss_card_wait(150);
    // Source timeout stops the card's emission/movement; keep the boss body on stage.
    loop { wait(1); }
}

async sub card_timeout() {
    // Source timeout (frame 3000) transitions with killAllAsync/enmKillAll; the Taiko retire,
    // the boss itself survives (exempt). In-flight bullets keep their natural tail.
    wait(3000);
    kill_all_enemies(KILL_SILENT);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_main);
    spawn card_timeout();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_CARD3, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// TH14 synthetic bullet aliases (native type 0..42 -> modern 0..23 same, 24..42 +1).
// See transcribe/th14/touhou-bullets.ecl; only the types this card fires.
// native 19 -> TH14_BIG_BALL2 (modern 19, 656), native 32 -> TH14_GLOW_BALL (modern 33, 880).
const TH14_BIG_BALL2: int = 656;
const TH14_GLOW_BALL: int = 880;
